package com.codetyper.app;
import android.os.*; import android.content.*; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.google.gson.Gson;
public class LessonActivity extends AppCompatActivity { Lesson l; EditText code; long started; int hearts=3;
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_lesson); l=new Gson().fromJson(getIntent().getStringExtra("lesson"),Lesson.class); started=System.currentTimeMillis(); ((TextView)findViewById(R.id.title)).setText(l.title); ((TextView)findViewById(R.id.code)).setText(l.code_to_type); ((TextView)findViewById(R.id.hint)).setText("Hint: "+l.hint); code=findViewById(R.id.input); findViewById(R.id.run).setOnClickListener(v->run()); code.setOnKeyListener((v,k,e)->{ if(e.getAction()==1) return false; return false;}); }
 void run(){ CodeTyperEngine.Result r=CodeTyperEngine.run(l,code.getText().toString(),System.currentTimeMillis()-started); if(r.success){ UserProgress p=UserProgress.load(this); p.xp+=l.xp_reward; p.hearts=5; p.completed.add(l.id); p.level=Math.max(p.level,l.level+1); p.save(this); Intent i=new Intent(this,ResultActivity.class); i.putExtra("ok",true);i.putExtra("out",r.output);i.putExtra("xp",l.xp_reward);i.putExtra("wpm",r.wpm);i.putExtra("acc",r.accuracy);startActivity(i);finish(); } else { hearts--; Toast.makeText(this,r.output+"  Hearts: "+hearts,Toast.LENGTH_SHORT).show(); if(hearts<=0){Intent i=new Intent(this,ResultActivity.class);i.putExtra("ok",false);i.putExtra("out","Game Over — retry the lesson.");startActivity(i);finish();} } }
}
